using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.UIElements;using TimelessEchoes.Upgrades;using TimelessEchoes.UI;using TimelessEchoes.UI.Toolkit;using References.UI;using TimelessEchoes.References.StatPanel;using Image=UnityEngine.UI.Image;
namespace TimelessEchoes.EditorTools {
 public static class ToolkitResourceInventoryMigration {
 [MenuItem("Tools/UI Toolkit/Import resource inventory reference")]
 public static void Import(){if(Application.isPlaying)throw new InvalidOperationException("Main Edit mode required");const string path="Assets/UI/Toolkit/";var ui=UnityEngine.Object.FindAnyObjectByType<ResourceInventoryUI>(FindObjectsInactive.Include);var so=new SerializedObject(ui);var wm=new SerializedObject(UnityEngine.Object.FindAnyObjectByType<TownWindowManager>(FindObjectsInactive.Include));var window=((GameObject)wm.FindProperty("inventory").FindPropertyRelative("window").objectReferenceValue).transform;var d=AssetDatabase.LoadAssetAtPath<ToolkitResourceInventoryDefinition>(path+"ResourceInventory.asset");if(!d){d=ScriptableObject.CreateInstance<ToolkitResourceInventoryDefinition>();AssetDatabase.CreateAsset(d,path+"ResourceInventory.asset");}var list=so.FindProperty("resources");d.resources=Enumerable.Range(0,list.arraySize).Select(i=>(Resource)list.GetArrayElementAtIndex(i).objectReferenceValue).Where(r=>r).ToArray();var slot=(ResourceUIReferences)so.FindProperty("slotPrefab").objectReferenceValue;var stat=(StatPanelReferences)so.FindProperty("statPanelReferences").objectReferenceValue;d.tierBorders=stat.tierBorderSprites.ToArray();d.tierBackgrounds=stat.tierBackgroundSprites.ToArray();d.selection=slot.selectionImage.sprite;d.title=window.Find("Image/Image").GetComponent<Image>().sprite;d.inset=window.Find("Image/ScrollViews").GetComponent<Image>().sprite;d.showTierBorder=so.FindProperty("showTierBorder").boolValue;d.showTierBackground=so.FindProperty("showTierBackground").boolValue;d.highlightDuration=so.FindProperty("highlightDuration").floatValue;EditorUtility.SetDirty(d);var go=new GameObject("Toolkit Resource Inventory");try{var screen=go.AddComponent<ToolkitResourceInventoryScreen>();var native=new SerializedObject(screen);native.FindProperty("definition").objectReferenceValue=d;native.FindProperty("theme").objectReferenceValue=AssetDatabase.LoadAssetAtPath<ToolkitTheme>(path+"Theme.asset");native.FindProperty("runtimeTheme").objectReferenceValue=AssetDatabase.LoadAssetAtPath<ThemeStyleSheet>(path+"Runtime.tss");native.FindProperty("textSettings").objectReferenceValue=AssetDatabase.LoadAssetAtPath<PanelTextSettings>(path+"TextSettings.asset");native.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.SaveAsPrefabAsset(go,path+"ResourceInventory.prefab");AssetDatabase.SaveAssets();}finally{UnityEngine.Object.DestroyImmediate(go);}}
 }
}
